head.infra/components/svc/main.tf:
locals {
  region = data.aws_region.current.region
}

data "aws_region" "current" {}

module "orders_queue" {
  source = "../../modules/sqs-queue"
  name   = "orders-${var.environment}"
}

resource "aws_db_instance" "db" {
  identifier          = "orders"
  instance_class      = "db.t4g.small"
  storage_encrypted   = true
  deletion_protection = false
}

resource "aws_iam_role" "task" {
  name               = "svc-task"
  assume_role_policy = jsonencode({ Statement = [{ Effect = "Allow", Principal = { Service = "ecs-tasks.amazonaws.com" }, Action = "sts:AssumeRole" }] })
}

data "aws_iam_policy_document" "inline" {
  statement {
    actions   = ["sqs:SendMessage"]
    effect    = "Allow"
    resources = [module.orders_queue.queue_arn]
  }
}

resource "aws_iam_role_policy" "inline" {
  role   = aws_iam_role.task.name
  policy = data.aws_iam_policy_document.inline.json
}

resource "aws_sqs_queue" "unrelated" {
  name = "unrelated"
}

head.infra/modules/sqs-queue/main.tf:
variable "name" {
  type = string
}

resource "aws_sqs_queue" "dlq" {
  name = "${var.name}-dlq"
}

resource "aws_sqs_queue" "queue" {
  name = var.name
  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq.arn
    maxReceiveCount     = 5
  })
}

output "queue_arn" {
  value = aws_sqs_queue.queue.arn
}

